PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entity ?entityLabel ?type ?summary ?category ?year WHERE {
    ?entity rdfs:label ?entityLabel .
    FILTER (?entityLabel = "훈민정음 창제" || ?entityLabel = "세종대왕" || ?entityLabel = "훈민정음" || ?entityLabel = "세종" || ?entityLabel = "정음 28자(훈민정음) 해석" || ?entityLabel = "훈민정음 서문" || ?entityLabel = "세종실록" || ?entityLabel = "공안 전면 개정" || ?entityLabel = "과전법 개정" || ?entityLabel = "고려시대")
